                  {presentation.label}
                </span>
                <span className="mt-0.5 block text-xs leading-4 text-muted-foreground">
                  {presentation.description}
                </span>
              </span>
              {isPending ? (
                <Loader2
                  className="mt-0.5 h-4 w-4 shrink-0 animate-spin text-muted-foreground"
                  aria-label={ui("Changing permissions")}
                />
              ) : isSelected ? (
                <Check
                  className="mt-0.5 h-4 w-4 shrink-0"
                  aria-label={ui("Selected")}
                />
              ) : null}
            </button>
          );
        })}
      </PopoverContent>
    </Popover>
  );
}

"""Host-neutral permission policy for automatic Turn execution."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from typing import Any, Protocol

from core.config import DeepCodeConfig, load_config_for_workspace
from core.domain.execution_permission import ExecutionPermissionMode


class AutomationPermissionPolicy(Protocol):
    """Resolve the permission snapshot for a workspace Automation Turn."""

    def resolve(self, workspace: str) -> ExecutionPermissionMode:
        """Return one explicit, durable execution mode."""


@dataclass(frozen=True, slots=True)
class WorkspaceAutomationPermissionPolicy:
    """Use explicit layered workspace configuration or a safe default.

    This resolver intentionally ignores the host surface and does not inspect
    Automation instructions. Resolution happens once at Turn admission and the
    typed result is persisted, so later workers consume the same decision.
    """

    config_loader: Callable[[str], DeepCodeConfig] = load_config_for_workspace
    default_mode: ExecutionPermissionMode = ExecutionPermissionMode.DEFAULT

    def resolve(self, workspace: str) -> ExecutionPermissionMode:
        security = getattr(self.config_loader(workspace), "security", None)
        raw = _explicit_permission_mode(security)
        if raw is None:
            return self.default_mode
        try:
            return ExecutionPermissionMode(raw.strip().lower())
        except ValueError:
            return self.default_mode


def _explicit_permission_mode(security: Any | None) -> str | None:
    if security is None:
        return None
    fields_set = getattr(security, "model_fields_set", None)
    if fields_set is None:
        fields_set = getattr(security, "__fields_set__", None)
    if fields_set is not None and "permission_mode" not in fields_set:
        return None
    value = getattr(security, "permission_mode", None)
    return str(value) if value is not None else None


__all__ = [
    "AutomationPermissionPolicy",
    "WorkspaceAutomationPermissionPolicy",
]

from __future__ import annotations

import pytest

from core.application.automation_permission_policy import (
    WorkspaceAutomationPermissionPolicy,
)
from core.config import DeepCodeConfig
from core.domain.execution_permission import ExecutionPermissionMode


@pytest.mark.parametrize(
    ("raw", "expected"),
    (
        ({}, ExecutionPermissionMode.DEFAULT),
        (
            {"security": {"permissionMode": "plan"}},
            ExecutionPermissionMode.PLAN,
        ),
        (
            {"security": {"permission_mode": "full_auto"}},
            ExecutionPermissionMode.FULL_AUTO,
        ),
        (
            {"security": {"permissionMode": "invalid"}},
            ExecutionPermissionMode.DEFAULT,
        ),
    ),
)
def test_workspace_policy_uses_explicit_config_or_safe_default(
    raw: dict,
    expected: ExecutionPermissionMode,
) -> None:
    config = DeepCodeConfig.model_validate(raw)
    policy = WorkspaceAutomationPermissionPolicy(
        config_loader=lambda _workspace: config,
    )

    assert policy.resolve("/workspace") is expected


def test_workspace_policy_does_not_inherit_host_environment(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setenv("DEEPCODE_PERMISSION_MODE", "full_auto")
    config = DeepCodeConfig.model_validate({})
    policy = WorkspaceAutomationPermissionPolicy(
        config_loader=lambda _workspace: config,
    )

    assert policy.resolve("/workspace") is ExecutionPermissionMode.DEFAULT

"""Permission checking for tool execution."""

from __future__ import annotations

import fnmatch
import logging
from dataclasses import dataclass

from openharness.config.settings import PermissionSettings
from openharness.permissions.modes import PermissionMode

log = logging.getLogger(__name__)

# Paths that are always denied regardless of permission mode or user config.
# These protect high-value credential and key material from LLM-directed access
# (including via prompt injection).  Patterns use fnmatch syntax and are matched
# against the fully-resolved absolute path produced by the query engine.
SENSITIVE_PATH_PATTERNS: tuple[str, ...] = (
    # SSH keys and config
    "*/.ssh/*",
    # AWS credentials
    "*/.aws/credentials",
    "*/.aws/config",
    # GCP credentials
    "*/.config/gcloud/*",
    # Azure credentials
    "*/.azure/*",
    # GPG keys
    "*/.gnupg/*",
    # Docker credentials
    "*/.docker/config.json",
    # Kubernetes credentials
    "*/.kube/config",
    # OpenHarness own credential stores
    "*/.openharness/credentials.json",
    "*/.openharness/copilot_auth.json",
)


@dataclass(frozen=True)
class PermissionDecision:
    """Result of checking whether a tool invocation may run."""

    allowed: bool
    requires_confirmation: bool = False
    reason: str = ""


@dataclass(frozen=True)
class PathRule:
    """A glob-based path permission rule."""

    pattern: str
    allow: bool  # True = allow, False = deny


class PermissionChecker:
    """Evaluate tool usage against the configured permission mode and rules."""

    def __init__(self, settings: PermissionSettings) -> None:
        self._settings = settings
        # Parse path rules from settings
        self._path_rules: list[PathRule] = []
        for rule in getattr(settings, "path_rules", []):
            pattern = getattr(rule, "pattern", None) or (rule.get("pattern") if isinstance(rule, dict) else None)
            allow = getattr(rule, "allow", True) if not isinstance(rule, dict) else rule.get("allow", True)
            if isinstance(pattern, str) and pattern.strip():
                self._path_rules.append(PathRule(pattern=pattern.strip(), allow=allow))
            else:
                log.warning(
                    "Skipping path rule with missing, empty, or non-string 'pattern' field: %r",
                    rule,
                )

    def evaluate(
        self,
        tool_name: str,
        *,
        is_read_only: bool,
        file_path: str | None = None,
        command: str | None = None,
    ) -> PermissionDecision:
        """Return whether the tool may run immediately."""
        # Built-in sensitive path protection — always active, cannot be
        # overridden by user settings or permission mode.  This is a
        # defence-in-depth measure against LLM-directed or prompt-injection
        # driven access to credential files.
        if file_path:
            for candidate_path in _policy_match_paths(file_path):
                for pattern in SENSITIVE_PATH_PATTERNS:
                    if fnmatch.fnmatch(candidate_path, pattern):
                        return PermissionDecision(
                            allowed=False,
                            reason=(
                                f"Access denied: {file_path} is a sensitive credential path "
                                f"(matched built-in pattern '{pattern}')"
                            ),
                        )

        # Explicit tool deny list
        if tool_name in self._settings.denied_tools:
            return PermissionDecision(allowed=False, reason=f"{tool_name} is explicitly denied")

        # Explicit tool allow list
        if tool_name in self._settings.allowed_tools:
            return PermissionDecision(allowed=True, reason=f"{tool_name} is explicitly allowed")

        # Check path-level rules
        if file_path and self._path_rules:
            for candidate_path in _policy_match_paths(file_path):
                for rule in self._path_rules:
                    if fnmatch.fnmatch(candidate_path, rule.pattern):
                        if not rule.allow:
                            return PermissionDecision(
                                allowed=False,
                                reason=f"Path {file_path} matches deny rule: {rule.pattern}",
                            )

        # Check command deny patterns (e.g. deny "rm -rf /")
        if command:
            for pattern in getattr(self._settings, "denied_commands", []):
                if isinstance(pattern, str) and fnmatch.fnmatch(command, pattern):
                    return PermissionDecision(
                        allowed=False,
                        reason=f"Command matches deny pattern: {pattern}",
                    )

        # Full auto: allow everything
        if self._settings.mode == PermissionMode.FULL_AUTO:
            return PermissionDecision(allowed=True, reason="Auto mode allows all tools")

        # Read-only tools always allowed
        if is_read_only:
            return PermissionDecision(allowed=True, reason="read-only tools are allowed")

        # Plan mode: block mutating tools
        if self._settings.mode == PermissionMode.PLAN:
            return PermissionDecision(
                allowed=False,
                reason="Plan mode blocks mutating tools until the user exits plan mode",
            )

        # Default mode: require confirmation for mutating tools
        bash_hint = _bash_permission_hint(command)
        reason = (
            "Mutating tools require user confirmation in default mode. "
            "Approve the prompt when asked, or run /permissions full_auto "
            "if you want to allow them for this session."
        )
        if bash_hint:
            reason = f"{reason} {bash_hint}"
        return PermissionDecision(
            allowed=False,
            requires_confirmation=True,
            reason=reason,
        )


def _policy_match_paths(file_path: str) -> tuple[str, ...]:
    """Return path forms that should participate in policy matching.

    Directory-scoped tools like ``grep`` and ``glob`` may operate on a root such
    as ``/home/user/.ssh``. Appending a trailing slash lets glob-style deny
    patterns like ``*/.ssh/*`` and ``/etc/*`` match the directory root itself.
    """
    normalized = file_path.rstrip("/")
    if not normalized:
        return (file_path,)
    return (normalized, normalized + "/")


def _bash_permission_hint(command: str | None) -> str:
    if not command:
        return ""
    lowered = command.lower()
    install_markers = (
        "npm install",
        "pnpm install",
        "yarn install",
        "bun install",
        "pip install",
        "uv pip install",
        "poetry install",
        "cargo install",
        "create-next-app",
        "npm create ",
        "pnpm create ",
        "yarn create ",
        "bun create ",
        "npx create-",
        "npm init ",
        "pnpm init ",
        "yarn init ",
    )
    if any(marker in lowered for marker in install_markers):
        return (
            "Package installation and scaffolding commands change the workspace, "
            "so they will not run automatically in default mode."
        )
    return ""

import { logForDebugging } from '../utils/debug.js'
import {
  isAtOrUnder,
  normalizePathForSandbox,
  pathSpellings,
  properAncestors,
  walkGlobPattern,
} from './sandbox-utils.js'

/**
 * A read-deny glob still needing more than this many mounts after collapsing
 * is logged at warn level (SRT_DEBUG) as a hint that the pattern is broad.
 * The expansion is never truncated, which would silently un-deny paths.
 */
const READ_DENY_GLOB_MOUNT_WARN_THRESHOLD = 256

/** The directory holding `p`, or '' for a root child. */
function parentOf(p: string): string {
  return p.slice(0, p.lastIndexOf('/'))
}

/**
 * Reduce the places a read-deny glob's matches really live to the ones whose
 * mount changes what the sandbox can read. A location is dropped only when a
 * kept proper ancestor's tmpfs already hides it and no re-exposer sits at the
 * ancestor or between the two.
 */
function collapseReadDenyLocations({
  locations,
  reExposedPaths,
}: {
  /** Absolute, symlink-free, trailing-slash-free paths. */
  locations: Iterable<string>
  /** allowRead/allowWrite paths the denyRead loop binds back over a tmpfs, as
   *  spelled and as resolved. */
  reExposedPaths: ReadonlySet<string>
}): Set<string> {
  // A proper ancestor is a proper string prefix, so lexicographic order
  // visits every ancestor before its descendants.
  const sorted = [...new Set(locations)].sort()
  const kept = new Set<string>()
  for (const location of sorted) {
    let reExposedBetween = reExposedPaths.has(location)
    let hidden = false
    for (const ancestor of properAncestors(location)) {
      // A re-exposer at the kept ancestor counts: the deny loop binds it back
      // over the tmpfs, so everything beneath needs its own mount.
      if (reExposedPaths.has(ancestor)) reExposedBetween = true
      if (kept.has(ancestor)) {
        hidden = true
        break
      }
    }
    if (!hidden || reExposedBetween) kept.add(location)
  }
  return kept
}

/**
 * Expand a read-deny glob into the paths bwrap should mount over, collapsed
 * against `reExposedPaths` (the caller's allowRead and allowWrite entries).
 * A pattern ending in `/**` also takes its directory form, so
 * `**\/build/**` yields one mount per `build/` directory. A match reached
 * through a symlink is listed where it really lives, and a directory the walk
 * could not list is denied whole. Sorted, so an ancestor precedes its
 * descendants.
 *
 * @param unlistableDirs - receives the returned locations that hide something
 * the walk could not enumerate, whether by being that directory or by
 * covering it. The Linux wrapper binds nothing back beneath one: what the
 * pattern matches under an allowed path in there was never found, and would
 * come back unmasked.
 */
export function expandReadDenyGlobLinux(
  globPattern: string,
  reExposedPaths: readonly string[],
  unlistableDirs?: Set<string>,
): string[] {
  const walk = walkGlobPattern(globPattern, {
    withDirectoryForm: true,
    followSymlinkedDirectories: true,
  })
  // Where a path the walk reported really lives: the denyRead loop mounts an
  // entry there, whatever spelling named it.
  const locationOf = (p: string): string => walk.realOf.get(p) ?? p
  // An unlisted directory hides whatever the pattern matches beneath it.
  const candidates = new Set([...walk.matches, ...walk.unlisted])
  if (walk.directoryMatches.length > 0) {
    // Everything beneath a directory-form match is itself a match (the
    // pattern ends in /**), so a directory with something to deny holds one.
    // An empty one gets no mount: it has nothing to deny, and as a tmpfs it
    // would swallow later writes. Compared where they live, since one
    // spelling of a directory is walked and the matches found through it are
    // reported at their real locations.
    const holdMatches = new Set(walk.matches.map(m => parentOf(locationOf(m))))
    for (const dir of walk.directoryMatches) {
      // A directory-form match that is a symlink counts in its own right:
      // one the walk did not list through (a link back up the tree, or a
      // further name for a directory already listed) has no match beneath
      // it, yet denies everything it reaches.
      if (holdMatches.has(locationOf(dir)) || walk.symlinks.has(dir)) {
        candidates.add(dir)
      }
    }
  }

  const locations = new Set<string>()
  /** Which spelling first put a location in the list, for the warning below. */
  const namedBy = new Map<string, string>()
  const addLocation = (location: string, candidate: string): void => {
    locations.add(location)
    if (!namedBy.has(location)) namedBy.set(location, candidate)
  }
  for (const candidate of candidates) {
    if (walk.symlinks.has(candidate) && !walk.realOf.has(candidate)) {
      if (!walk.uninspectableLinks.has(candidate)) {
        // A link that resolves to nothing denies nothing, and bwrap cannot
        // mount on the link itself.
        logForDebugging(
          `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} does not resolve, skipping`,
        )
        continue
      }
      // A link whose target is there but cannot be looked at: kept under its
      // own spelling, where the denyRead loop's stand-in rule hides the
      // nearest directory above it that can be inspected.
      logForDebugging(
        `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} leads somewhere that cannot be inspected; denying what holds it`,
        { level: 'warn' },
      )
      addLocation(candidate, candidate)
      continue
    }
    const location = locationOf(candidate)
    if (location !== '/') {
      addLocation(location, candidate)
      continue
    }
    // A link to the root. A tmpfs there would wipe every mount placed before
    // it and the pivot would promote it, booting the command on an empty
    // tree, and bwrap cannot mount on the link itself. The nearest directory
    // above the link stands in for it, as for an entry that cannot be
    // inspected — never the root itself.
    const standIn = locationOf(parentOf(candidate))
    if (standIn === '' || standIn === '/') {
      logForDebugging(
        `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} resolves to / and nothing but / holds it, skipping`,
        { level: 'warn' },
      )
      continue
    }
    logForDebugging(
      `[Sandbox Linux] denyRead glob "${globPattern}": ${candidate} resolves to /; denying ${standIn}, which holds it, instead`,
      { level: 'warn' },
    )
    addLocation(standIn, candidate)
  }

  const reExposed = new Set(
    reExposedPaths.flatMap(p => pathSpellings(normalizePathForSandbox(p))),
  )
  const mounts = collapseReadDenyLocations({
    locations,
    reExposedPaths: reExposed,
  })

  // Which mounts stand for something the walk could not enumerate: the
  // unlistable directory itself when it survived the collapse, otherwise the
  // kept ancestor that hides it.
  for (const unlisted of walk.unlisted) {
    const location = locationOf(unlisted)
    if (mounts.has(location)) {
      unlistableDirs?.add(location)
      continue
    }
    for (const ancestor of properAncestors(location)) {
      if (mounts.has(ancestor)) {
        unlistableDirs?.add(ancestor)
        break
      }
    }
  }

  logForDebugging(
    `[Sandbox Linux] Expanded denyRead glob "${globPattern}": ${walk.matches.length} matches -> ${mounts.size} mounts`,
  )
  for (const mount of mounts) {
    // A matched link decides what is hidden for the whole sandbox: a
    // `certs/*` entry pointing at a database directory mounts a tmpfs over
    // that directory, not over anything the pattern names.
    if (walk.baseLocation !== '' && !isAtOrUnder(mount, walk.baseLocation)) {
      logForDebugging(
        `[Sandbox Linux] denyRead glob "${globPattern}" hides ${mount}, outside ${walk.baseLocation}: reached through ${namedBy.get(mount) === mount ? 'a symlinked directory' : namedBy.get(mount)}`,
        { level: 'warn' },
      )
    }
  }
  if (mounts.size > READ_DENY_GLOB_MOUNT_WARN_THRESHOLD) {
    logForDebugging(
      `[Sandbox Linux] denyRead glob "${globPattern}" still needs ${mounts.size} mounts after collapsing ` +
        `(threshold ${READ_DENY_GLOB_MOUNT_WARN_THRESHOLD}); each is a separate bwrap mount at sandbox start. ` +
        `Prefer denying the enclosing directories.`,
      { level: 'warn' },
    )
  }
  return [...mounts].sort()
}

import { describe, it, expect, beforeAll, afterAll } from 'bun:test'
import { spawnSync } from 'node:child_process'
import {
  existsSync,
  mkdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from 'node:fs'
import { homedir, tmpdir } from 'node:os'
import { join } from 'node:path'
import { wrapCommandWithSandboxMacOS } from '../../src/sandbox/macos-sandbox-utils.js'
import { wrapCommandWithSandboxLinux } from '../../src/sandbox/linux-sandbox-utils.js'
import { createMitmCA, disposeMitmCA } from '../../src/sandbox/mitm-ca.js'
import type {
  FsReadRestrictionConfig,
  FsWriteRestrictionConfig,
} from '../../src/sandbox/sandbox-schemas.js'
import { isLinux, isMacOS, isSupportedPlatform } from '../helpers/platform.js'

/**
 * Tests for the allowRead (allowWithinDeny) feature.
 *
 * allowRead re-allows read access within regions blocked by denyRead.
 * allowRead takes precedence over denyRead — the opposite of write,
 * where denyWrite takes precedence over allowWrite.
 */
describe('allowRead precedence over denyRead', () => {
  const TEST_BASE_DIR = join(tmpdir(), 'allow-read-test-' + Date.now())
  const TEST_DENIED_DIR = join(TEST_BASE_DIR, 'denied')
  const TEST_ALLOWED_SUBDIR = join(TEST_DENIED_DIR, 'allowed')
  const TEST_SECRET_FILE = join(TEST_DENIED_DIR, 'secret.txt')
  const TEST_ALLOWED_FILE = join(TEST_ALLOWED_SUBDIR, 'visible.txt')
  const TEST_SECRET_CONTENT = 'TOP_SECRET'
  const TEST_ALLOWED_CONTENT = 'VISIBLE_DATA'

  beforeAll(() => {
    if (!isSupportedPlatform) return

    mkdirSync(TEST_ALLOWED_SUBDIR, { recursive: true })
    writeFileSync(TEST_SECRET_FILE, TEST_SECRET_CONTENT)
    writeFileSync(TEST_ALLOWED_FILE, TEST_ALLOWED_CONTENT)
  })

  afterAll(() => {
    if (existsSync(TEST_BASE_DIR)) {
      rmSync(TEST_BASE_DIR, { recursive: true, force: true })
    }
  })

  describe('macOS Seatbelt', () => {
    it.if(isMacOS)('should deny reading a file in a denied directory', () => {
      const readConfig: FsReadRestrictionConfig = {
        denyOnly: [TEST_DENIED_DIR],
        allowWithinDeny: [],
      }

      const wrappedCommand = wrapCommandWithSandboxMacOS({
        command: `cat ${TEST_SECRET_FILE}`,
        needsNetworkRestriction: false,
        readConfig,
        writeConfig: undefined,
      })

      const result = spawnSync(wrappedCommand, {
        shell: true,
        encoding: 'utf8',
        timeout: 5000,
      })

      expect(result.status).not.toBe(0)
      expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
    })

    it.if(isMacOS)(
      'should allow reading a file in an allowWithinDeny subdirectory',
      () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = wrapCommandWithSandboxMacOS({
          command: `cat ${TEST_ALLOWED_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).toBe(0)
        expect(result.stdout).toContain(TEST_ALLOWED_CONTENT)
      },
    )

    it.if(isMacOS)(
      'should still deny reading files outside the re-allowed subdirectory',
      () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = wrapCommandWithSandboxMacOS({
          command: `cat ${TEST_SECRET_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).not.toBe(0)
        expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
      },
    )
  })

  describe('Linux bwrap', () => {
    it.if(isLinux)(
      'should deny reading a file in a denied directory',
      async () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [],
        }

        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_SECRET_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).not.toBe(0)
        expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
      },
    )

    it.if(isLinux)(
      'should allow reading a file in an allowWithinDeny subdirectory',
      async () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_ALLOWED_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).toBe(0)
        expect(result.stdout).toContain(TEST_ALLOWED_CONTENT)
      },
    )

    it.if(isLinux)(
      'should still deny reading files outside the re-allowed subdirectory',
      async () => {
        const readConfig: FsReadRestrictionConfig = {
          denyOnly: [TEST_DENIED_DIR],
          allowWithinDeny: [TEST_ALLOWED_SUBDIR],
        }

        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_SECRET_FILE}`,
          needsNetworkRestriction: false,
          readConfig,
          writeConfig: undefined,
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).not.toBe(0)
        expect(result.stdout).not.toContain(TEST_SECRET_CONTENT)
      },
    )

    // Regression: the write-path skip check in the allowRead re-bind loop was
    // too broad — it skipped any allowPath under ANY allowWrite, not just
    // writes actually re-bound under this tmpfs. With allowWrite as an
    // ancestor of denyRead (not wiped, not re-bound), allowRead under it was
    // skipped and left sitting in the empty tmpfs.
    // Shape: allowWrite: [~], denyRead: [~/.ssh], allowRead: [~/.ssh/known_hosts].
    it.if(isLinux)(
      'should re-allow under denyRead when allowWrite is an ancestor of the deny',
      async () => {
        const wrappedCommand = await wrapCommandWithSandboxLinux({
          command: `cat ${TEST_ALLOWED_FILE}`,
          needsNetworkRestriction: false,
          readConfig: {
            denyOnly: [TEST_DENIED_DIR],
            allowWithinDeny: [TEST_ALLOWED_SUBDIR],
          },
          writeConfig: {
            allowOnly: [TEST_BASE_DIR], // ancestor of denyRead
            denyWithinAllow: [],
          },
        })

        const result = spawnSync(wrappedCommand, {
          shell: true,
          encoding: 'utf8',
          timeout: 5000,
        })

        expect(result.status).toBe(0)
        expect(result.stdout).toContain(TEST_ALLOWED_CONTENT)
      },
    )
  })
})

/**
 * Regression: denyRead: ['/'] + allowRead: [<project>] used to deny everything.
 *
 * macOS: (subpath "/") denies the root inode; no allowWithinDeny subpath covers
 *   "/", so dyld SIGABRTs before exec. Fix emits (allow file-read* (literal "/")).
 * Linux: --tmpfs / wiped all prior mounts, and the carve-out prefix check
 *   startsWith('/' + '/') never matched. Fix expands '/' into its children.
 *
 * Test dir lives under $HOME (not tmpdir) so the macOS /tmp → /private/tmp
 * symlink doesn't confuse Seatbelt path matching.
 */
describe('allowRead carve-out with denyRead at filesystem root (issue #10)', () => {
  const TEST_DIR = join(
    homedir(),
    '.sandbox-runtime-test-root-deny-' + Date.now(),
  )
  const TEST_FILE = join(TEST_DIR, 'visible.txt')
  const TEST_CONTENT = 'ROOT_CARVE_OUT'
  // Paths needed for sh/cat to load at all when the whole filesystem is denied.
  // /private covers /tmp and /var (macOS symlinks). /lib* for Linux ld.so.
  const EXEC_DEPS = [
    '/bin',
    '/usr',
    '/lib',
    '/lib64',
    '/System',
    '/private',
    '/dev',
    '/etc',
  ]

  beforeAll(() => {
    if (!isSupportedPlatform) return
    mkdirSync(TEST_DIR, { recursive: true })
    writeFileSync(TEST_FILE, TEST_CONTENT)
  })

  afterAll(() => {
    if (existsSync(TEST_DIR)) {
      rmSync(TEST_DIR, { recursive: true, force: true })
    }
  })

  it.if(isMacOS)('macOS: re-allows carve-out under a root-level deny', () => {
    const readConfig: FsReadRestrictionConfig = {
      denyOnly: ['/'],
      allowWithinDeny: [TEST_DIR, ...EXEC_DEPS],
    }

    // EXEC_DEPS covers /bin and /usr but not /opt/homebrew — pin the shell
    // so denying the filesystem root doesn't break execvp on Homebrew-bash Macs.
    const wrappedCommand = wrapCommandWithSandboxMacOS({
      command: `cat ${TEST_FILE}`,
      needsNetworkRestriction: false,
      readConfig,
      writeConfig: undefined,
      binShell: '/bin/bash',
    })

    const result = spawnSync(wrappedCommand, {
      shell: true,
      encoding: 'utf8',
      timeout: 5000,
    })

    expect(result.status).toBe(0)
    expect(result.stdout).toContain(TEST_CONTENT)
  })

  it.if(isMacOS)(
    'macOS: still denies paths outside the carve-out under a root-level deny',
    () => {
      const outside = join(homedir(), '.bashrc')
      const readConfig: FsReadRestrictionConfig = {
        denyOnly: ['/'],
        allowWithinDeny: [TEST_DIR, ...EXEC_DEPS],
      }

      const wrappedCommand = wrapCommandWithSandboxMacOS({
        command: `cat ${outside} 2>/dev/null; true`,
        needsNetworkRestriction: false,
        readConfig,
        writeConfig: undefined,
        binShell: '/bin/bash',
      })

      const result = spawnSync(wrappedCommand, {
        shell: true,
        encoding: 'utf8',
        timeout: 5000,
      })

      // Process must exec (no SIGABRT) and stdout must be empty (cat denied)
      expect(result.status).toBe(0)
      expect(result.stdout).toBe('')
    },
  )

  it.if(isLinux)(
    'Linux: re-allows carve-out under a root-level deny',
    async () => {
      const readConfig: FsReadRestrictionConfig = {
        denyOnly: ['/'],
        allowWithinDeny: [TEST_DIR, ...EXEC_DEPS],
      }

      // allowAllUnixSockets: true bypasses the seccomp path — otherwise the
      // apply-seccomp binary under <repo>/vendor/ is hidden by the root deny.
      const wrappedCommand = await wrapCommandWithSandboxLinux({
        command: `cat ${TEST_FILE}`,
        needsNetworkRestriction: false,
        readConfig,
        writeConfig: undefined,
        allowAllUnixSockets: true,
      })

      const result = spawnSync(wrappedCommand, {
        shell: true,
        encoding: 'utf8',
        timeout: 5000,
      })

      expect(result.status).toBe(0)
      expect(result.stdout).toContain(TEST_CONTENT)
    },
  )

  it.if(isLinux)(
    'Linux: still denies paths outside the carve-out under a root-level deny',
    async () => {
      const outside = join(homedir(), '.bashrc')
      const readConfig: FsReadRestrictionConfig = {
        denyOnly: ['/'],
        allowWithinDeny: [TEST_DIR, ...EXEC_DEPS],
      }

      const wrappedCommand = await wrapCommandWithSandboxLinux({
        command: `cat ${outside} 2>/dev/null; true`,
        needsNetworkRestriction: false,
        readConfig,
        writeConfig: undefined,
        allowAllUnixSockets: true,
      })

      const result = spawnSync(wrappedCommand, {
        shell: true,
        encoding: 'utf8',
        timeout: 5000,
      })

      expect(result.status).toBe(0)
      expect(result.stdout).toBe('')
    },
  )

  it.if(isLinux)(
    'Linux: preserves write binds when denyRead ancestor wipes them',
    async () => {
      const writeTarget = join(TEST_DIR, 'written.txt')
      const wrappedCommand = await wrapCommandWithSandboxLinux({
        command: `echo WRITE_OK > ${writeTarget} && cat ${writeTarget}`,
        needsNetworkRestriction: false,
        readConfig: {
          denyOnly: ['/'],
          allowWithinDeny: [...EXEC_DEPS],
        },
        writeConfig: {
          allowOnly: [TEST_DIR],
          denyWithinAllow: [],
        },
        allowAllUnixSockets: true,
      })

      const result = spawnSync(wrappedCommand, {
        shell: true,
        encoding: 'utf8',
        timeout: 5000,
      })

      expect(result.status).toBe(0)
      expect(result.stdout).toContain('WRITE_OK')
    },
  )
})

